<?php
declare(strict_types=1);
if(!isset($db,$action)||!($db instanceof PDO)||!function_exists('h')||session_status()!==PHP_SESSION_ACTIVE){http_response_code(403);exit('Otevřete tuto stránku přes administraci Odladění.');}
$isSuper=$user&&$user['role']==='superadmin';$manage=$action==='users';
if(!$user||($manage&&!$isSuper)){http_response_code(403);exit('Přístup odepřen.');}
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(empty($_SESSION['csrf'])||!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Potvrzení vypršelo. Obnovte stránku.');
  $cmd=(string)($_POST['cmd']??'');$target=strtolower(trim((string)($_POST['email']??'')));
  if($cmd==='revoke_own'){$q=$db->prepare('UPDATE users SET token_epoch=token_epoch+1 WHERE email=?');$q->execute([$user['email']]);odlAccountsAudit($db,$user['email'],'chatgpt_revoked');$notice='Dosavadní autorizace ChatGPT tohoto účtu byly odvolány. Nové propojení potvrďte znovu.';}
  elseif(!$isSuper)throw new RuntimeException('Pouze superadministrátor.');
  elseif($cmd==='membership'){odlAccountsAssign($db,$user,$target,(string)($_POST['site']??''),(string)($_POST['membership_role']??''));$notice='Přidělení webu bylo uloženo.';}
  elseif(in_array($cmd,['disable','enable','reject','revoke'],true)){
   $u=odlAccountsUser($db,$target);if(!$u||$u['role']==='superadmin')throw new RuntimeException('Tento účet nelze tímto způsobem změnit.');
   if($cmd==='revoke'){$q=$db->prepare('UPDATE users SET token_epoch=token_epoch+1 WHERE email=?');$q->execute([$target]);odlAccountsAudit($db,$user['email'],'chatgpt_revoked','',$target);}
   else odlAccountsReview($db,$user,$target,$cmd==='enable'?'approved':'rejected');
   $notice=$cmd==='enable'?'Uživatel byl schválen. Nyní mu můžete přidělit web.':($cmd==='revoke'?'Propojení ChatGPT bylo odvoláno.':'Přístup uživatele byl zablokován.');
  }else throw new RuntimeException('Neznámá operace.');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$people=$isSuper?$db->query("SELECT u.email,u.role,u.enabled,u.last_login,COALESCE(a.status,'approved') AS approval_status,a.reviewed_by,a.reviewed_at FROM users u LEFT JOIN account_approvals a ON a.email=u.email ORDER BY CASE WHEN a.status='pending' THEN 0 ELSE 1 END,u.email")->fetchAll(PDO::FETCH_ASSOC):[];
$allSites=$isSuper?odlAccountsSites($db,$user):[];$members=$isSuper?$db->query('SELECT m.*,u.enabled FROM account_memberships m JOIN users u ON u.email=m.email ORDER BY m.email')->fetchAll(PDO::FETCH_ASSOC):[];
$assigned=odlAccountsSites($db,$user);
function accountCsrf():void {echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';}
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$manage?'Uživatelé a přidělené weby':'Propojit s ChatGPT'?> — Odladění</title><style>body{font:15px/1.55 system-ui;background:#eef3ff;color:#172343;margin:0}main{max-width:1120px;margin:24px auto;padding:0 16px}section{background:#fff;padding:24px;border:1px solid #dce5f5;border-radius:18px;margin:18px 0}a{color:#2163e9}button,.btn{padding:10px 14px;background:#2163e9;color:white;border:0;border-radius:9px;font:inherit;cursor:pointer}input,select{font:inherit;padding:10px;border:1px solid #cad5e8;border-radius:8px;max-width:100%;min-width:0;box-sizing:border-box}form.inline{display:flex;gap:8px;flex-wrap:wrap;align-items:center}form.inline>*{flex:1 1 160px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px 10px;border-bottom:1px solid #e4eaf4;vertical-align:top}td{overflow-wrap:anywhere}th{white-space:nowrap}.bad{color:#b42335}.good{color:#14864b}.notice{padding:14px;background:#e0f5e9;border-radius:10px}.error{background:#ffe7e7}.actions{display:flex;flex-wrap:wrap;gap:6px}.actions form{display:inline}.actions button{font-size:13px;padding:7px 10px}.person{padding:6px 0}.muted{color:#6b7892}h1{font-size:26px}code{overflow-wrap:anywhere}@media(max-width:650px){main{padding:0 12px;margin:16px auto}section{padding:16px}h1{font-size:23px}td,th{padding:9px 7px}}</style></head><body><main><a href="/console/">← Přehled webů</a> · <a href="/console/?action=chatgpt">Propojit s ChatGPT</a><?php if($isSuper):?> · <a href="/console/?action=users">Uživatelé a přidělení</a><?php endif;?><h1><?=$manage?'Uživatelé a přidělené weby':'Propojit s ChatGPT'?></h1><p><?=h($user['email'])?></p>
<?php if($notice):?><p class="notice" role="status"><?=h($notice)?></p><?php endif;if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?>
<?php if($manage):?><section><h2>Registrace přes Google</h2><p>Nový člověk otevře <a href="/console/">přihlášení Odladění</a> a přihlásí se vlastním Google účtem. Vznikne žádost čekající na vaše schválení. Dokud uživatele neschválíte, nemůže používat správu ani propojení ChatGPT. Po schválení mu přidělíte jeden nebo více webů.</p><p>Jeden web může spravovat více lidí. Superadministrátor má přístup ke všem webům.</p></section>
<section><h2>Přidělit web</h2><form method="post" class="inline"><?php accountCsrf();?><input type="hidden" name="cmd" value="membership"><select name="email" aria-label="Uživatel" required><option value="">Vyberte uživatele</option><?php foreach($people as $p)if($p['role']!=='superadmin'&&!empty($p['enabled'])):?><option value="<?=h($p['email'])?>"><?=h($p['email'])?><?=$p['enabled']?'':' (zakázaný)'?></option><?php endif;?></select><select name="site" aria-label="Web" required><option value="">Vyberte web</option><?php foreach($allSites as $s):?><option value="<?=h($s['site_url'])?>"><?=h($s['site_name'])?></option><?php endforeach;?></select><select name="membership_role" aria-label="Oprávnění"><option value="admin">Správce webu</option><option value="viewer">Pouze prohlížení</option></select><button>Přidělit / změnit</button></form></section>
<section><h2>Kdo spravuje jednotlivé weby</h2><div class="table-wrap"><table><thead><tr><th>Web</th><th>Přidělení lidé</th></tr></thead><tbody><?php foreach($allSites as $s):?><tr><td><?=h($s['site_name'])?></td><td><?php $found=false;foreach($members as $m)if($m['site_url']===$s['site_url']):$found=true;?><div class="person"><?=h($m['email'])?> · <?=$m['role']==='admin'?'správce':'prohlížení'?><?=$m['enabled']?'':' · účet zakázaný'?><form method="post" style="display:inline"><?php accountCsrf();?><input type="hidden" name="cmd" value="membership"><input type="hidden" name="email" value="<?=h($m['email'])?>"><input type="hidden" name="site" value="<?=h($s['site_url'])?>"><input type="hidden" name="membership_role" value="remove"><button>Odebrat</button></form></div><?php endif;if(!$found):?><span class="muted">Pouze superadministrátor</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section><h2>Uživatelé a schvalování</h2><p><strong><?=count(array_filter($people,static fn($p)=>$p['approval_status']==='pending'))?> čeká na schválení</strong> · Žádný nový účet nezíská přístup automaticky.</p><div class="table-wrap"><table><thead><tr><th>Google účet</th><th>Stav</th><th>Weby</th><th>Poslední přihlášení</th><th>Akce</th></tr></thead><tbody><?php foreach($people as $p):?><tr><td><?=h($p['email'])?><?=$p['role']==='superadmin'?' · superadministrátor':''?></td><td class="<?=$p['enabled']?'good':'bad'?>"><?=$p['role']==='superadmin'?'Superadministrátor':($p['approval_status']==='pending'?'Čeká na schválení':($p['enabled']?'Schválený':'Zablokovaný / zamítnutý'))?><?php if(!empty($p['reviewed_by'])):?><br><small><?=h($p['reviewed_by'])?> · <?=h((string)$p['reviewed_at'])?> UTC</small><?php endif;?></td><td><?php if($p['role']==='superadmin'):?>Všechny<?php else:$cnt=0;foreach($members as $m)if($m['email']===$p['email'])$cnt++;echo $cnt;if(!$cnt):?> · čeká na přidělení<?php endif;endif;?></td><td><?=h((string)($p['last_login']??'Dosud nepřihlášen'))?></td><td><div class="actions"><?php if($p['role']!=='superadmin')foreach([($p['enabled']?'disable':'enable')=>($p['enabled']?'Zablokovat účet':'Schválit uživatele'),'reject'=>'Zamítnout přístup','revoke'=>'Odvolat ChatGPT'] as $cmd=>$label):?><form method="post"><?php accountCsrf();?><input type="hidden" name="cmd" value="<?=h($cmd)?>"><input type="hidden" name="email" value="<?=h($p['email'])?>"><button><?=h($label)?></button></form><?php endforeach;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<section><h2>Historie přístupů a operací</h2><p class="muted">Posledních 100 záznamů. „requested“ znamená přijatý požadavek; výsledek změny se ověřuje v potvrzení dané operace. Záznam neobsahuje hesla, klíče ani upravovaný obsah.</p><div class="table-wrap"><table><thead><tr><th>Čas (UTC)</th><th>Kdo</th><th>Událost</th><th>Web / účet</th><th>Stav</th></tr></thead><tbody><?php foreach($db->query('SELECT * FROM account_audit ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC) as $e):?><tr><td><?=h($e['at'])?></td><td><?=h($e['actor'])?></td><td><?=h($e['event'])?></td><td><?=h($e['site_url'].' '.$e['target'])?></td><td><?=h($e['outcome'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:?><section><h2>Propojit s ChatGPT</h2><?php try{$connection=odlAccountsConnection($db,$user,dirname(__DIR__,2).'/private');}catch(Throwable $e){$connection=null;}?><p class="notice"><?php if($connection===null):?>Stav propojení se nyní nepodařilo ověřit.<?php elseif($connection['count']):?><strong>Propojení je autorizované</strong> · <?=h((string)$connection['count'])?> aktivní autorizace. Přístup se při používání automaticky obnovuje.<?php else:?><strong>Pro tento účet nemáme doložené aktivní propojení.</strong> Starší administrátorské připojení může fungovat samostatně.<?php endif;?></p><p><a class="btn" href="https://chatgpt.com/plugins" target="_blank" rel="noopener noreferrer">Otevřít pluginy v ChatGPT ↗</a></p><p>Vyberte <strong>Odladění – správa pluginů</strong> a potvrďte připojení vlastním Google účtem. Pokud plugin v nabídce nemáte, musí vám správce nejdříve zpřístupnit jeho instalaci. Toto tlačítko otevře katalog; samo plugin nenainstaluje.</p><p>Připojení je možné tam, kde je aplikace Odladění pro váš účet dostupná. Registrace v Odladění ji do ChatGPT sama nenainstaluje. Dostupnost závisí také na prostředí a oprávněních vašeho účtu.</p><ol><li>V ChatGPT zahajte připojení aplikace <strong>Odladění – správa pluginů</strong>.</li><li>Na autorizační stránce se přihlaste Google účtem <strong><?=h($user['email'])?></strong>.</li><li>Zkontrolujte účet a přidělené weby a potvrďte propojení.</li></ol><p>Přihlášení do ChatGPT stejným Google účtem samo o sobě propojení neudělá. Je potřeba potvrdit přístup aplikace.</p><p>Adresa rozhraní pro připojení: <code>https://plaginy.odladeni.cz/mcp/</code></p><p>Vaše oprávnění se kontrolují při každém požadavku. Správa serveru a přidělování dalších lidí patří superadministrátorovi.</p></section><section><h2>Moje weby</h2><?php if(!$assigned):?><p>Účet je připravený. Čekáte na přidělení webu superadministrátorem.</p><?php else:?><ul><?php foreach($assigned as $s):?><li><?=h($s['site_name'])?> — <?=$s['membership_role']==='admin'?'správce':'pouze prohlížení'?></li><?php endforeach;?></ul><?php endif;?></section><section><h2>Odvolat moje propojení</h2><p>Tímto zneplatníte dosavadní autorizace svého ChatGPT. Přihlášení do Odladění zůstane aktivní.</p><form method="post"><?php accountCsrf();?><input type="hidden" name="cmd" value="revoke_own"><button>Odvolat propojení ChatGPT</button></form><p class="muted">Již otevřená přihlášení přímo ve WordPressu mají vlastní dobu platnosti. Toto tlačítko nemaže samostatné účty WordPressu.</p></section><?php endif;?></main></body></html><?php exit;
